calls.content:
{
  "summary": "Enhance the existing URL shortener to record redirect analytics, expose per-link analytics, and reject URLs that point back to the shortener while preserving all existing endpoint behavior.",
  "changeType": "brownfield",
  "functional": [
    "When an existing short link is successfully redirected, record one click event containing the redirect timestamp and the value of the HTTP Referer header, or no referrer when the header is absent.",
    "Expose an analytics endpoint for an individual short link at GET /links/{code}/analytics.",
    "The analytics response must include total clicks for the link, click counts for each of the last 30 calendar days, and the five most frequently observed non-empty referrers.",
    "The 30-day click series must include days with zero clicks and cover the current UTC calendar day plus the preceding 29 UTC calendar days.",
    "Referrer rankings must be ordered by descending click count, with ascending referrer value used as the deterministic tie-breaker.",
    "Requests for analytics for an unknown short code must use the existing link-not-found error behavior and response contract.",
    "Short-link creation must reject a destination URL that points to the shortener itself, including URLs with any path on the shortener's configured public origin.",
    "Self-referencing destination rejection must use the existing invalid-URL error behavior and response contract.",
    "Existing endpoints, HTTP methods, successful response bodies, error response bodies, and redirect behavior must remain unchanged except that self-referencing destinations are newly rejected."
  ],
  "nonFunctional": [
    "Analytics recording must not change the redirect destination, redirect status code, or existing redirect response headers.",
    "Analytics data must be associated with the short link code and must distinguish separate redirect requests.",
    "The implementation must preserve the existing application's API compatibility for all previously valid requests.",
    "Referrer values must be handled as received from the HTTP Referer header without exposing credentials or other newly introduced secrets.",
    "Analytics aggregation must be deterministic for repeated requests over the same recorded data."
  ],
  "outOfScope": [
    "Changing the existing short-code generation algorithm or link creation response schema.",
    "Tracking analytics for failed redirects, unknown short codes, or requests that do not produce the existing redirect response.",
    "User accounts, authentication, authorization, rate limiting, or per-user analytics.",
    "IP address, user-agent, geographic, device, or campaign-parameter analytics.",
    "Deleting, exporting, or administratively modifying click records.",
    "Changing the existing persistence technology or adding cross-instance analytics synchronization.",
    "Changing the existing API documentation beyond documenting the new analytics endpoint and self-link validation behavior."
  ],
  "openQuestions": [
    {
      "question": "What exact JSON property names and shape should the new analytics response use?",
      "assumption": "Use {\"totalClicks\": number, \"clicksPerDay\": [{\"date\": \"YYYY-MM-DD\", \"clicks\": number}], \"topReferrers\": [{\"referrer\": string, \"clicks\": number}]}.",
      "answer": ""
    },
    {
      "question": "How should the public origin of the shortener be identified for self-reference validation?",
      "assumption": "Add or use a configurable shortener.base-url value; compare the destination URL's scheme, host, and effective port with that origin, regardless of destination path. If the property is absent, derive the origin from the incoming link-creation request.",
      "answer": ""
    },
    {
      "question": "Should a Referer header with an empty value be included in the top-referrer ranking?",
      "assumption": "No. Missing or blank Referer values are recorded as absent and excluded from topReferrers, while still counting toward totalClicks and clicksPerDay.",
      "answer": ""
    },
    {
      "question": "What timezone defines a calendar day for the clicksPerDay aggregation?",
      "assumption": "UTC, with the current UTC date included and exactly 30 date entries returned.",
      "answer": ""
    },
    {
      "question": "Must analytics survive application restart or be shared across multiple application instances?",
      "assumption": "No. Follow the existing repository's persistence behavior and store analytics using the same application lifecycle and persistence approach unless the repository already provides durable/shared storage.",
      "answer": ""
    },
    {
      "question": "Which HTTP status should be returned when a self-referencing destination is submitted?",
      "assumption": "Reuse the status and ErrorResponse body currently produced for InvalidUrlException, without introducing a new error contract.",
      "answer": ""
    },
    {
      "question": "Should redirects that include a Referer header with credentials or sensitive query data be normalized or redacted?",
      "assumption": "No normalization or redaction is added in this change; store the header value as supplied by the client, subject to the existing application's data handling.",
      "answer": ""
    }
  ],
  "acceptanceCriteria": [
    {
      "id": "AC1",
      "criterion": "Given a valid existing short code, when a client requests its redirect endpoint and receives the existing successful redirect response, then exactly one click event is recorded for that short code."
    },
    {
      "id": "AC2",
      "criterion": "Given a redirect request with Referer: https://example.com/page, when analytics are requested for the short code, then the response includes that exact referrer with a click count incremented by one."
    },
    {
      "id": "AC3",
      "criterion": "Given a redirect request without a Referer header, when analytics are requested, then totalClicks and the relevant daily count increase by one and no blank or null entry appears in topReferrers."
    },
    {
      "id": "AC4",
      "criterion": "Given multiple successful redirects for one short code, when GET /links/{code}/analytics is called, then it returns HTTP 200 with totalClicks equal to the number of recorded successful redirects."
    },
    {
      "id": "AC5",
      "criterion": "Given recorded redirects distributed across dates in the previous 29 UTC days and the current UTC day, when analytics are requested, then clicksPerDay contains exactly 30 entries, one for every UTC date in that inclusive range, with correct counts including zero-count dates."
    },
    {
      "id": "AC6",
      "criterion": "Given more than five distinct non-empty referrers, when analytics are requested, then topReferrers contains at most five entries ordered by descending click count and then ascending referrer value for ties."
    },
    {
      "id": "AC7",
      "criterion": "Given a short code with no recorded redirects, when GET /links/{code}/analytics is called, then it returns HTTP 200 with totalClicks 0, 30 zero-valued daily entries, and an empty topReferrers list."
    },
    {
      "id": "AC8",
      "criterion": "Given an unknown short code, when GET /links/{code}/analytics is called, then the endpoint returns the same HTTP status and error response structure used by the existing unknown-link behavior."
    },
    {
      "id": "AC9",
      "criterion": "Given a destination URL whose scheme, host, and effective port match the configured shortener public origin, when the client submits it to the existing link-creation endpoint, then creation is rejected using the existing invalid-URL status and error response contract."
    },
    {
      "id": "AC10",
      "criterion": "Given a valid external destination URL, when the client submits it to the existing link-creation endpoint, then link creation succeeds with the existing status and response body unchanged."
    },
    {
      "id": "AC11",
      "criterion": "Given any previously valid non-self-referencing link, when its redirect endpoint is requested, then the status, Location header, and response body remain identical to the existing behavior apart from the internal analytics side effect."
    },
    {
      "id": "AC12",
      "criterion": "Given a failed redirect request for an unknown short code, when the request completes, then no click event is included in analytics for any link."
    }
  ],
  "decisions": [
    {
      "title": "Classify the change as brownfield",
      "rationale": "The repository contains an implemented URL shortener with controllers, services, persistence, and integration tests rather than only the application template.",
      "alternatives": [
        "Classify as greenfield based only on the scenario hint",
        "Treat analytics and validation as separate projects"
      ]
    },
    {
      "title": "Use a link-scoped analytics endpoint",
      "rationale": "The requirement asks for analytics for one link, and /links/{code}/analytics is consistent with the existing resource-oriented API structure.",
      "alternatives": [
        "Use /analytics/{code}",
        "Add analytics to the existing link response"
      ]
    },
    {
      "title": "Record only successful redirects",
      "rationale": "A click is defined here as a request that reaches the existing redirect response; failed lookups do not redirect and should not inflate link analytics.",
      "alternatives": [
        "Record every request reaching the redirect controller",
        "Record only requests with a non-empty Referer header"
      ]
    },
    {
      "title": "Use UTC and include zero-count days",
      "rationale": "UTC avoids deployment-location-dependent results, and a complete 30-day series makes the API predictable and directly usable for charts.",
      "alternatives": [
        "Use the server's local timezone",
        "Return only dates that have clicks",
        "Use a client-supplied timezone"
      ]
    },
    {
      "title": "Exclude blank referrers from rankings",
      "rationale": "An absent or blank referrer is not a meaningful referring source, but its redirect must still count toward total and daily totals.",
      "alternatives": [
        "Rank blank referrers as an explicit '(direct)' category",
        "Discard click events with no referrer entirely"
      ]
    },
    {
      "title": "Reuse existing validation and not-found error contracts",
      "rationale": "The requirement explicitly requires existing endpoint responses to keep working unchanged, so new rejection behavior should use the application's established exception handling.",
      "alternatives": [
        "Introduce a new error code and response schema",
        "Return a generic HTTP error without the existing ErrorResponse body"
      ]
    },
    {
      "title": "Detect self-links by configured public origin",
      "rationale": "Comparing the destination origin rather than one exact short URL prevents loops through any shortener path while avoiding false positives for unrelated external hosts.",
      "alternatives": [
        "Reject only destinations matching the exact configured base URL",
        "Reject any URL containing the shortener's hostname text",
        "Reject all URLs submitted from the same client host"
      ]
    }
  ]
}

{
  "summary": "Enhance the existing URL shortener with per-redirect analytics and reject destination URLs that point back to the shortener, while preserving all existing endpoint behavior and response contracts.",
  "changeType": "brownfield",
  "functional": [
    "Record an analytics event for each successful short-code redirect, including the redirect timestamp and the value of the incoming HTTP Referer header, if present.",
    "Expose GET /api/links/{code}/analytics for an existing short code.",
    "The analytics response must include the total number of recorded redirects for the link.",
    "The analytics response must include click counts for each calendar day in the last 30 UTC calendar days, including days with zero clicks.",
    "The analytics response must include at most the five most frequently occurring non-empty referrer values, ordered by descending click count and then deterministically by referrer value for ties.",
    "Analytics for a link with no recorded redirects must return total clicks of zero, zero-valued entries for all 30 requested days, and an empty top-referrers collection.",
    "Requests for analytics for an unknown short code must use the existing link-not-found HTTP status and error response contract.",
    "When creating a short link, reject a destination URL whose origin matches the configured public origin of this shortener. This prevents links to the shortener itself from creating redirect loops.",
    "A rejected self-referential destination must use the existing invalid-URL HTTP status and error response contract.",
    "Existing link-creation, link-retrieval, and redirect endpoints must retain their current paths, successful response bodies, status codes, and behavior for valid non-self-referential destinations.",
    "Redirect requests must continue to return the existing redirect response; recording analytics must not alter the redirect target, status, or response headers."
  ],
  "nonFunctional": [
    "The analytics endpoint must be available under the existing API prefix exactly as GET /api/links/{code}/analytics.",
    "Analytics timestamps must be recorded with sufficient precision to identify the event instant and must be converted to UTC for daily aggregation.",
    "The analytics response must be deterministic: daily entries use ascending UTC date order, and referrer ties use lexicographic referrer ordering.",
    "Analytics recording and querying must use the application's configured persistence mechanism and remain available across normal application restarts to the same extent as link data.",
    "The implementation must not expose credentials, secrets, or sensitive configuration values in API responses or logs.",
    "Analytics aggregation must be scoped to the requested short code and must not include events for other links.",
    "The feature must be covered by automated tests for redirect recording, absent referrers, daily aggregation, top-referrer limiting and ordering, unknown codes, and self-referential URL rejection."
  ],
  "outOfScope": [
    "Changing the existing endpoint paths or response schemas other than adding the new analytics endpoint.",
    "Counting requests that do not resolve to an existing short code as clicks.",
    "Tracking analytics dimensions other than timestamp and referrer, such as IP address, user agent, geographic location, or authenticated user.",
    "Providing configurable analytics date ranges, pagination, CSV export, dashboards, or deletion endpoints.",
    "Backfilling analytics for redirects that occurred before this feature is deployed.",
    "Changing URL validation rules unrelated to preventing destinations on the shortener's own configured origin."
  ],
  "openQuestions": [
    {
      "question": "What exact JSON property names and wrapper shape should the analytics response use?",
      "assumption": "Use a response with totalClicks (number), clicksPerDay (array of objects containing date and clicks), and topReferrers (array of objects containing referrer and clicks).",
      "answer": ""
    },
    {
      "question": "Which public origin should be used to detect a destination pointing back to the shortener when deployment occurs behind a proxy or under a custom domain?",
      "assumption": "Use a configured public base URL/origin supplied through application configuration; do not infer it from an individual request. If no separate public URL is configured, use the application's configured server origin.",
      "answer": ""
    },
    {
      "question": "Should the Referer header value be normalized before aggregation?",
      "assumption": "Store and aggregate the header value as received, without URL parsing, canonicalization, or case normalization; omit empty or absent values from topReferrers while still counting the click.",
      "answer": ""
    },
    {
      "question": "What does 'last 30 days' mean at the boundary?",
      "assumption": "Return the current UTC calendar date and the preceding 29 UTC calendar dates, for exactly 30 dates inclusive.",
      "answer": ""
    },
    {
      "question": "Should every URL on the shortener's origin be rejected, or only URLs matching its redirect route?",
      "assumption": "Reject every absolute destination URL whose scheme, host, and effective port match the configured public origin. This is the safest interpretation of preventing links back to the shortener and avoids route-pattern loopholes.",
      "answer": ""
    }
  ],
  "acceptanceCriteria": [
    {
      "id": "AC1",
      "criterion": "Given an existing short code and no prior analytics events, when GET /api/links/{code}/analytics is called, the API returns HTTP 200 with totalClicks equal to 0, exactly 30 clicksPerDay entries covering the current UTC date and previous 29 UTC dates in ascending order, each with clicks equal to 0, and an empty topReferrers array."
    },
    {
      "id": "AC2",
      "criterion": "Given a valid short code, when its redirect endpoint is requested once with Referer: https://example.com/article, the existing redirect status, Location value, and response contract are unchanged, and GET /api/links/{code}/analytics subsequently reports totalClicks equal to 1 and one click for the UTC date of the redirect."
    },
    {
      "id": "AC3",
      "criterion": "Given a redirect request without a Referer header or with an empty Referer header, when the redirect succeeds, analytics totalClicks increases by one, the relevant daily count increases by one, and the missing or empty value does not appear in topReferrers."
    },
    {
      "id": "AC4",
      "criterion": "Given multiple successful redirects for one link from several referrers, when GET /api/links/{code}/analytics is called, topReferrers contains each distinct non-empty referrer with its click count, ordered by descending count and then lexicographically by referrer when counts tie."
    },
    {
      "id": "AC5",
      "criterion": "Given more than five distinct non-empty referrers for one link, when GET /api/links/{code}/analytics is called, topReferrers contains exactly the five highest-ranked referrers under the specified ordering and excludes all remaining referrers."
    },
    {
      "id": "AC6",
      "criterion": "Given redirect events both inside and outside the current UTC 30-day window, when GET /api/links/{code}/analytics is called, totalClicks includes all recorded redirect events while clicksPerDay includes only events whose UTC calendar date is within the returned 30 dates."
    },
    {
      "id": "AC7",
      "criterion": "Given an unknown short code, when GET /api/links/{code}/analytics is called, the API returns the existing link-not-found status and error response shape rather than a successful analytics response."
    },
    {
      "id": "AC8",
      "criterion": "Given a create-link request whose absolute destination has the same scheme, host, and effective port as the configured public origin, when the request is submitted, the API rejects it using the existing invalid-URL status and error response shape and does not create a link."
    },
    {
      "id": "AC9",
      "criterion": "Given a create-link request whose destination has an origin different from the configured public origin and otherwise passes existing validation, when the request is submitted, link creation succeeds with the existing status and response body unchanged."
    },
    {
      "id": "AC10",
      "criterion": "Given existing valid create, retrieve, and redirect API use cases, when those endpoints are exercised after the change, their paths, status codes, response bodies, redirect targets, and existing error behavior remain unchanged except for the newly required self-origin rejection."
    }
  ],
  "decisions": [
    {
      "title": "Place analytics under the existing API prefix",
      "rationale": "The required endpoint is GET /api/links/{code}/analytics, consistent with the existing GET /api/links/{code} resource API and the reviewer feedback.",
      "alternatives": [
        "Expose analytics at /links/{code}/analytics.",
        "Expose analytics at /api/analytics/{code}."
      ]
    },
    {
      "title": "Count only successful redirects as clicks",
      "rationale": "A click is represented by a request that resolves to a stored short link and produces the existing redirect response; unknown-code requests are not redirects for a link.",
      "alternatives": [
        "Count every request reaching the redirect controller, including unknown codes.",
        "Count only redirects that receive a follow-up confirmation from the client."
      ]
    },
    {
      "title": "Use UTC calendar dates for aggregation",
      "rationale": "UTC provides stable, deployment-independent day boundaries and makes the 30-day response deterministic across servers and clients.",
      "alternatives": [
        "Use the server's local timezone.",
        "Use the requesting client's timezone."
      ]
    },
    {
      "title": "Return all 30 daily buckets including zero-count days",
      "rationale": "A fixed 30-entry series is directly usable by clients and makes the requested last-30-days window observable even when there are no clicks on some days.",
      "alternatives": [
        "Return only dates that have at least one click.",
        "Return a map keyed by date without guaranteeing ordering."
      ]
    },
    {
      "title": "Exclude absent referrers from top-referrer rankings",
      "rationale": "The requirement asks for top referrers, while an absent Referer is not a referrer; the click is still counted in total and daily metrics.",
      "alternatives": [
        "Represent absent referrers as a null or '(direct)' bucket.",
        "Discard clicks without a referrer entirely."
      ]
    },
    {
      "title": "Reject the entire configured public origin",
      "rationale": "Rejecting all destinations on the shortener's own origin prevents alternate paths, aliases, or future redirect routes from creating loops and is safer than matching only one route pattern.",
      "alternatives": [
        "Reject only the exact generated short-link URL pattern.",
        "Reject only the redirect path while allowing other same-origin paths."
      ]
    },
    {
      "title": "Preserve existing error contracts",
      "rationale": "The requirement explicitly requires existing endpoints and responses to keep working unchanged; new validation failures should therefore reuse the existing invalid-URL handling.",
      "alternatives": [
        "Introduce a new error status or error schema for self-referential URLs.",
        "Return a generic server error."
      ]
    }
  ]
}

{
  "impactedFiles": [
    {
      "path": "src/main/java/com/example/shortener/Link.java",
      "changeKind": "modify",
      "reason": "Optionally expose the relationship needed for persisted redirect analytics while preserving the existing link fields and clickCount response behavior."
    },
    {
      "path": "src/main/java/com/example/shortener/LinkController.java",
      "changeKind": "modify",
      "reason": "Add GET /api/links/{code}/analytics and pass configured-origin validation through the existing create flow without changing existing response schemas."
    },
    {
      "path": "src/main/java/com/example/shortener/LinkService.java",
      "changeKind": "modify",
      "reason": "Record a persisted redirect event with timestamp and Referer value during follow, and aggregate analytics for a requested code."
    },
    {
      "path": "src/main/java/com/example/shortener/RedirectController.java",
      "changeKind": "modify",
      "reason": "Read the incoming Referer header and pass it to the redirect service while retaining the existing 302 response and Location header."
    },
    {
      "path": "src/main/java/com/example/shortener/LinkRepository.java",
      "changeKind": "modify",
      "reason": "Support any link lookup or query needed by analytics while retaining the existing click-count increment behavior."
    },
    {
      "path": "src/main/java/com/example/shortener/UrlValidator.java",
      "changeKind": "modify",
      "reason": "Reject absolute HTTP or HTTPS destinations whose scheme, host, and effective port match the configured public origin, while preserving all existing URL validation errors."
    },
    {
      "path": "src/main/java/com/example/shortener/RedirectEvent.java",
      "changeKind": "create",
      "reason": "Persist one analytics record per successful short-code redirect, including the associated link, event timestamp, and nullable or empty Referer value."
    },
    {
      "path": "src/main/java/com/example/shortener/RedirectEventRepository.java",
      "changeKind": "create",
      "reason": "Provide persistence access for redirect events and scoped retrieval or aggregation by short code."
    },
    {
      "path": "src/main/java/com/example/shortener/LinkAnalyticsResponse.java",
      "changeKind": "create",
      "reason": "Define the new analytics response contract containing totalClicks, 30 ordered daily entries, and ordered top referrers."
    },
    {
      "path": "src/main/resources/application.yml",
      "changeKind": "modify",
      "reason": "Add the configured public origin used to detect self-referential destinations, with the existing server origin as the default."
    },
    {
      "path": "docs/api.md",
      "changeKind": "modify",
      "reason": "Document the new analytics endpoint, response shape, and self-origin rejection without changing existing endpoint documentation."
    },
    {
      "path": "src/test/java/com/example/shortener/UrlShortenerIntegrationTest.java",
      "changeKind": "modify",
      "reason": "Extend existing integration coverage to verify Referer capture, absent Referer handling, unchanged redirect responses, analytics totals, and self-referential URL rejection."
    },
    {
      "path": "src/test/java/com/example/shortener/UrlValidatorTest.java",
      "changeKind": "modify",
      "reason": "Add validation coverage for origin and effective-port matching while retaining coverage for existing accepted and rejected URL forms."
    },
    {
      "path": "src/test/java/com/example/shortener/AnalyticsIntegrationTest.java",
      "changeKind": "create",
      "reason": "Add focused endpoint tests for zero-event analytics, 30 UTC calendar days, daily aggregation, historical total clicks, absent referrers, top-five limiting and tie ordering, link scoping, and unknown codes."
    }
  ],
  "impactedApis": [
    {
      "endpoint": "POST /api/links",
      "change": "Destinations matching the configured public origin are rejected with the existing invalid-URL 400 ProblemDetail contract; valid external destinations retain the existing status and response body.",
      "backwardCompatible": false
    },
    {
      "endpoint": "GET /{code}",
      "change": "Each successful redirect records timestamp and Referer analytics, but the redirect status, Location header, and response body remain unchanged. Unknown codes retain the existing 404 contract.",
      "backwardCompatible": true
    },
    {
      "endpoint": "GET /api/links/{code}",
      "change": "No response or behavior change is intended; clickCount continues to represent the existing link click counter.",
      "backwardCompatible": true
    },
    {
      "endpoint": "GET /api/links/{code}/analytics",
      "change": "New endpoint returning totalClicks, exactly 30 ascending UTC date entries in clicksPerDay, and up to five deterministically ordered topReferrers. Unknown codes use the existing link-not-found status and error response.",
      "backwardCompatible": true
    }
  ],
  "dataChanges": [
    {
      "entity": "RedirectEvent",
      "schema": "Add a persisted redirect-events table containing an identifier, link association or short-code scope, an instant timestamp, and a nullable Referer string.",
      "migrationImpact": "With the current JPA ddl-auto=update configuration, the table is created without changing existing links. Existing links have no backfilled events, so their new analytics initially report zero clicks."
    },
    {
      "entity": "Link",
      "schema": "Existing clickCount remains unchanged and continues supporting existing LinkResponse values; analytics events are stored separately rather than replacing the counter.",
      "migrationImpact": "Existing API consumers remain compatible. The separate event store permits total analytics clicks and the legacy clickCount to remain consistent for newly recorded redirects."
    },
    {
      "entity": "RedirectEvent.timestamp",
      "schema": "Store an instant with sufficient precision, such as Instant or an equivalent UTC-capable database timestamp.",
      "migrationImpact": "Aggregation converts timestamps to UTC calendar dates. Existing persisted data has no events and requires no conversion."
    }
  ],
  "testsToUpdate": [
    {
      "path": "src/test/java/com/example/shortener/UrlShortenerIntegrationTest.java",
      "changes": [
        "Assert redirect status and Location remain unchanged when a Referer is supplied.",
        "Assert redirect events are recorded with a Referer and without a Referer.",
        "Assert a configured-origin destination is rejected with the existing 400 ProblemDetail shape.",
        "Retain existing create, retrieve, redirect, unknown-code, and concurrency assertions."
      ]
    },
    {
      "path": "src/test/java/com/example/shortener/UrlValidatorTest.java",
      "changes": [
        "Cover same-origin rejection.",
        "Cover case-insensitive scheme and host matching and effective default-port equivalence.",
        "Cover acceptance of different origins and non-default ports."
      ]
    },
    {
      "path": "src/test/java/com/example/shortener/AnalyticsIntegrationTest.java",
      "changes": [
        "Verify a link with no events returns totalClicks 0, exactly 30 zero-valued UTC dates, and empty topReferrers.",
        "Verify successful redirects increment totals and the correct UTC day.",
        "Verify absent or empty Referer values count as clicks but are excluded from topReferrers.",
        "Verify referrer counts, descending-count ordering, lexicographic tie ordering, and five-item limiting.",
        "Verify events outside the 30-day window remain in totalClicks but not clicksPerDay.",
        "Verify analytics are scoped to the requested code.",
        "Verify unknown analytics codes use the existing not-found response."
      ]
    }
  ],
  "risks": [
    "Recording an event in the same transaction as clickCount can make a persistence failure turn an otherwise valid redirect into a server error; transaction boundaries must preserve atomicity without changing normal redirect behavior.",
    "Concurrent redirects can lose analytics events or produce inconsistent legacy clickCount values if event insertion and counter increment are not transactionally and safely handled.",
    "Incorrect UTC conversion or date-boundary calculation can return the wrong 30-day window, especially around midnight and daylight-saving transitions.",
    "Origin comparison can incorrectly reject or allow self-links if default ports, case normalization, proxy configuration, or malformed configured origins are handled inconsistently.",
    "Persisting raw Referer values can create large database values or expose sensitive URL query data; the implementation must enforce a safe column size and must not log the values.",
    "Using application startup configuration as the public origin may reject legitimate links or fail to reject self-links when deployment configuration is missing or incorrect.",
    "Adding a path-variable analytics route alongside GET /api/links/{code} requires route specificity to ensure /analytics is dispatched to the analytics endpoint rather than treated as a short code.",
    "Existing in-memory H2 configuration does not provide analytics persistence across process restarts; production persistence must use the same durable configured database mechanism as link data."
  ],
  "decisions": [
    {
      "title": "Store analytics events in a separate entity and table",
      "rationale": "The existing Link clickCount cannot support timestamps, referrer aggregation, historical totals, or daily analytics without changing its meaning or storing an unbounded collection.",
      "alternatives": [
        "Replace clickCount with a serialized analytics payload on Link",
        "Add denormalized daily and referrer counters to Link"
      ]
    },
    {
      "title": "Use the configured public origin rather than request headers",
      "rationale": "The requirement explicitly avoids inferring the public origin from individual requests and must remain reliable behind proxies or custom domains.",
      "alternatives": [
        "Infer origin from HttpServletRequest",
        "Compare only against the origin used to generate the current response URL"
      ]
    },
    {
      "title": "Keep the existing clickCount field and response unchanged",
      "rationale": "Existing link retrieval contracts must continue working unchanged, while the new event table provides the richer analytics model.",
      "alternatives": [
        "Remove clickCount from LinkResponse",
        "Compute clickCount dynamically from redirect events"
      ]
    },
    {
      "title": "Aggregate analytics in UTC using the current date plus the preceding 29 dates",
      "rationale": "This exactly implements the specified inclusive 30 UTC calendar-day window and provides deterministic ascending output including zero days.",
      "alternatives": [
        "Use a rolling 30 timespan from the current instant",
        "Use the server's local timezone"
      ]
    },
    {
      "title": "Store Referer values as received and exclude null or empty values from ranking",
      "rationale": "The specification requires no URL normalization while still counting redirects with missing or empty referrers.",
      "alternatives": [
        "Canonicalize referrers by parsing and normalizing URLs",
        "Use a placeholder value for missing referrers"
      ]
    },
    {
      "title": "Use existing JPA schema auto-update for the new table",
      "rationale": "The repository currently has no migration framework or migration scripts, and ddl-auto=update is the configured persistence mechanism.",
      "alternatives": [
        "Introduce a migration tool and versioned migration scripts",
        "Persist analytics only in memory"
      ]
    }
  ]
