  "decisions": [
    {
      "title": "Store analytics as a separate event entity",
      "rationale": "The existing clickCount field and LinkResponse contract must remain unchanged, while per-event timestamp and referrer data require one durable row per redirect.",
      "alternatives": [
        "Replace clickCount with event-derived counts; rejected because it changes existing semantics and makes the existing response contract harder to preserve.",
        "Store serialized analytics JSON on Link; rejected because it is difficult to query, update concurrently, and aggregate efficiently."
      ]
    },
    {
      "title": "Use the Link association rather than only a duplicated short-code string",
      "rationale": "A foreign-key association scopes events to the canonical link and avoids ambiguity if code handling changes, while queries can still filter by code through the association.",
      "alternatives": [
        "Store only shortCode text; rejected because it permits orphaned or inconsistent analytics rows.",
        "Use a bidirectional collection on Link; rejected because it is unnecessary for the API and can cause large object-graph loads."
      ]
    },
    {
      "title": "Use an injectable UTC Clock",
      "rationale": "UTC calendar boundaries must be deterministic and testable, especially around midnight.",
      "alternatives": [
        "Call Instant.now() directly; rejected because date-boundary tests become nondeterministic.",
        "Use server-local time; rejected because the requirement explicitly defines UTC aggregation."
      ]
    },
    {
      "title": "Record the event and legacy counter atomically",
      "rationale": "A successful redirect should have consistent legacy and analytics state; an insertion failure must not silently return an untracked redirect.",
      "alternatives": [
        "Best-effort event insertion after the response; rejected because events can be lost and there is no external queue or retry infrastructure.",
        "Persist only the event and derive clickCount; rejected because existing clickCount behavior and response compatibility must be preserved."
      ]
    },
    {
      "title": "Normalize configured and destination origins by scheme, host, and effective port",
      "rationale": "This prevents route and path loopholes and treats omitted default ports consistently with explicit default ports.",
      "alternatives": [
        "Compare complete URLs; rejected because different paths on the same host can still loop through the shortener.",
        "Infer origin from each create request; rejected because proxy headers and request origin are not a reliable configured public identity.",
        "Reject only the redirect path; rejected because other paths on the shortener origin can still create unsafe self-references."
      ]
    },
    {
      "title": "Preserve raw non-empty Referer values",
      "rationale": "The requirement calls for the header value as received and does not require canonicalization; preserving it makes aggregation predictable.",
      "alternatives": [
        "Parse and canonicalize URLs; rejected because it changes the supplied value and introduces unnecessary URL semantics.",
        "Normalize case; rejected because referrer values are aggregated as received and ordering must be deterministic on those values."
      ]
    },
    {
      "title": "Generate all 30 daily entries in the service",
      "rationale": "Explicit date generation guarantees exactly 30 ascending entries, including zero-count days, regardless of database grouping behavior.",
      "alternatives": [
        "Return only dates present in the database; rejected because zero-valued days are required.",
        "Use a database-specific calendar series query; rejected because it reduces H2 portability and is unnecessary for a 30-day window."
      ]
    },
    {
      "title": "Keep the H2 configuration and persistence lifecycle unchanged",
      "rationale": "The feature must use the application's existing persistence mechanism and remain compatible with the current single-service setup.",
      "alternatives": [
        "Add an external database or analytics store; rejected because external infrastructure is out of scope.",
        "Add a new dependency for analytics aggregation; rejected because Spring Data JPA queries and Java aggregation are sufficient."
      ]
    }
  ]
