{"files":[{"path":"src/main/java/com/example/shortener/PublicOriginConfiguration.java","content":"package com.example.shortener;

import java.net.URI;
import java.net.URISyntaxException;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

@Component
public class PublicOriginConfiguration {

    private final String scheme;
    private final String host;
    private final int port;

    public PublicOriginConfiguration(
            @Value("${app.public-origin:}") String configuredOrigin,
            @Value("${server.port:8080}") int serverPort,
            @Value("${server.ssl.enabled:false}") boolean sslEnabled) {
        String origin = configuredOrigin == null || configuredOrigin.isBlank()
                ? (sslEnabled ? "https" : "http") + "://localhost:" + serverPort
                : configuredOrigin;
        URI uri;
        try {
            uri = new URI(origin);
        } catch (URISyntaxException exception) {
            throw new IllegalStateException("app.public-origin must be a valid URI", exception);
        }
        if (!uri.isAbsolute() || uri.getScheme() == null || uri.getHost() == null
                || !(uri.getScheme().equalsIgnoreCase("http")
                || uri.getScheme().equalsIgnoreCase("https"))) {
            throw new IllegalStateException("app.public-origin must be an absolute HTTP or HTTPS origin");
        }
        this.scheme = uri.getScheme().toLowerCase(java.util.Locale.ROOT);
        this.host = uri.getHost().toLowerCase(java.util.Locale.ROOT);
        this.port = effectivePort(this.scheme, uri.getPort());
    }

    public boolean matches(URI destination) {
        if (destination == null || destination.getScheme() == null || destination.getHost() == null) {
            return false;
        }
        String destinationScheme = destination.getScheme().toLowerCase(java.util.Locale.ROOT);
        String destinationHost = destination.getHost().toLowerCase(java.util.Locale.ROOT);
        return scheme.equals(destinationScheme)
                && host.equals(destinationHost)
                && port == effectivePort(destinationScheme, destination.getPort());
    }

    private static int effectivePort(String scheme, int explicitPort) {
        if (explicitPort >= 0) {
            return explicitPort;
        }
        return "https".equalsIgnoreCase(scheme) ? 443 : 80;
    }
}
"},{"path":"src/main/java/com/example/shortener/UrlValidator.java","content":"package com.example.shortener;

import java.net.URI;
import java.net.URISyntaxException;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Component;

@Component
public class UrlValidator {

    private final PublicOriginConfiguration publicOrigin;

    @Autowired
    public UrlValidator(PublicOriginConfiguration publicOrigin) {
        this.publicOrigin = publicOrigin;
    }

    public UrlValidator() {
        this.publicOrigin = null;
    }

    public void validate(String value) {
        if (value == null || value.isBlank()) {
            throw new InvalidUrlException("url is required and must not be blank");
        }

        try {
            URI uri = new URI(value);
            String scheme = uri.getScheme();
            if (!uri.isAbsolute()
                    || scheme == null
                    || !(scheme.equalsIgnoreCase("http") || scheme.equalsIgnoreCase("https"))
                    || uri.getHost() == null) {
                throw new InvalidUrlException("url must be an absolute HTTP or HTTPS URL");
            }
            if (publicOrigin != null && publicOrigin.matches(uri)) {
                throw new InvalidUrlException("url must not point to this shortener");
            }
        } catch (URISyntaxException exception) {
            throw new InvalidUrlException("url must be a valid absolute HTTP or HTTPS URL");
        }
    }
}
"},{"path":"src/main/java/com/example/shortener/RedirectEvent.java","content":"package com.example.shortener;

import java.time.Instant;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Index;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.ManyToOne;
import jakarta.persistence.Table;

@Entity
@Table(name = "redirect_events", indexes = {
        @Index(name = "idx_redirect_events_link_time", columnList = "link_id,occurred_at"),
        @Index(name = "idx_redirect_events_link_referrer", columnList = "link_id,referrer")
})
public class RedirectEvent {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY, optional = false)
    @JoinColumn(name = "link_id", nullable = false)
    private Link link;

    @Column(name = "occurred_at", nullable = false)
    private Instant occurredAt;

    @Column(name = "referrer", length = 2048)
    private String referrer;

    protected RedirectEvent() {
    }

    public RedirectEvent(Link link, Instant occurredAt, String referrer) {
        this.link = link;
        this.occurredAt = occurredAt;
        this.referrer = referrer;
    }

    public Instant getOccurredAt() {
        return occurredAt;
    }

    public String getReferrer() {
        return referrer;
    }
}
