{"files":[{"path":"src/test/java/com/example/shortener/AnalyticsAndSelfOriginIntegrationTest.java","content":"package com.example.shortener;

import static org.assertj.core.api.Assertions.assertThat;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.header;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import java.time.LocalDate;
import java.util.List;
import java.util.Map;

import com.jayway.jsonpath.JsonPath;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.MvcResult;

@SpringBootTest
@AutoConfigureMockMvc
class AnalyticsAndSelfOriginIntegrationTest {

    @Autowired
    private MockMvc mockMvc;

    @Test
    void newLinkAnalyticsContainsExactlyThirtyUtcDaysWithZeros() throws Exception {
        String code = create("https://analytics-empty.example/item");

        MvcResult result = mockMvc.perform(get("/api/links/{code}/analytics", code))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.totalClicks").value(0))
                .andExpect(jsonPath("$.clicksPerDay").isArray())
                .andExpect(jsonPath("$.clicksPerDay.length()").value(30))
                .andExpect(jsonPath("$.clicksPerDay[0].date")
                        .value(LocalDate.now(java.time.Clock.systemUTC()).minusDays(29).toString()))
                .andExpect(jsonPath("$.clicksPerDay[29].date")
                        .value(LocalDate.now(java.time.Clock.systemUTC()).toString()))
                .andExpect(jsonPath("$.topReferrers").isEmpty())
                .andReturn();

        List<Map<String, Object>> days = JsonPath.read(
                result.getResponse().getContentAsString(), "$.clicksPerDay");
        assertThat(days).hasSize(30);
        assertThat(days).allSatisfy(day ->
                assertThat(((Number) day.get("clicks")).longValue()).isZero());
    }

    @Test
    void redirectPreserves302LocationAndRecordsReferrerAndMissingReferrer() throws Exception {
        String destination = "https://analytics-redirect.example/item";
        String code = create(destination);

        mockMvc.perform(get("/{code}", code).header("Referer", "https://example.com/article"))
                .andExpect(status().isFound())
                .andExpect(header().string("Location", destination));
        mockMvc.perform(get("/{code}", code).header("Referer", ""))
                .andExpect(status().isFound())
                .andExpect(header().string("Location", destination));
        mockMvc.perform(get("/{code}", code))
                .andExpect(status().isFound())
                .andExpect(header().string("Location", destination));

        mockMvc.perform(get("/api/links/{code}/analytics", code))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.totalClicks").value(3))
                .andExpect(jsonPath("$.topReferrers.length()").value(1))
                .andExpect(jsonPath("$.topReferrers[0].referrer").value("https://example.com/article"))
                .andExpect(jsonPath("$.topReferrers[0].clicks").value(1));
    }

    @Test
    void topReferrersUseCountThenLexicographicOrderAndLimitToFive() throws Exception {
        String code = create("https://analytics-referrers.example/item");
        redirect(code, "zeta");
        redirect(code, "alpha");
        redirect(code, "alpha");
        redirect(code, "beta");
        redirect(code, "beta");
        redirect(code, "charlie");
        redirect(code, "delta");
        redirect(code, "echo");
        redirect(code, "foxtrot");
        redirect(code, "golf");

        mockMvc.perform(get("/api/links/{code}/analytics", code))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.totalClicks").value(10))
                .andExpect(jsonPath("$.topReferrers.length()").value(5))
                .andExpect(jsonPath("$.topReferrers[0].referrer").value("alpha"))
                .andExpect(jsonPath("$.topReferrers[1].referrer").value("beta"))
                .andExpect(jsonPath("$.topReferrers[2].referrer").value("charlie"))
                .andExpect(jsonPath("$.topReferrers[3].referrer").value("delta"))
                .andExpect(jsonPath("$.topReferrers[4].referrer").value("echo"));
    }

    @Test
    void unknownAnalyticsCodeUsesExistingNotFoundContract() throws Exception {
        mockMvc.perform(get("/api/links/{code}/analytics", "unknown-analytics"))
                .andExpect(status().isNotFound())
                .andExpect(jsonPath("$.detail").isNotEmpty());
    }

    @Test
    void selfOriginDestinationIsRejectedWithoutCreatingLink() throws Exception {
        mockMvc.perform(post("/api/links")
                        .contentType("application/json")
                        .content("{\"url\":\"http://localhost:8080/loop\"}"))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.detail").value("url must not point to this shortener"));
    }

    private String create(String url) throws Exception {
        MvcResult result = mockMvc.perform(post("/api/links")
                        .contentType("application/json")
                        .content("{\"url\":\"" + url + "\"}"))
                .andExpect(status().isCreated())
                .andReturn();
        return JsonPath.read(result.getResponse().getContentAsString(), "$.code");
    }

    private void redirect(String code, String referrer) throws Exception {
        mockMvc.perform(get("/{code}", code).header("Referer", referrer))
                .andExpect(status().isFound());
    }
}
"},{"path":"src/test/java/com/example/shortener/PublicOriginAndUrlValidatorTest.java","content":"package com.example.shortener;

import static org.assertj.core.api.Assertions.assertThatCode;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import org.junit.jupiter.api.Test;

class PublicOriginAndUrlValidatorTest {

    @Test
    void rejectsSameOriginRegardlessOfPathAndCase() {
        PublicOriginConfiguration origin = new PublicOriginConfiguration(
                "HTTP://Shortener.Example:80", 8080, false);
        UrlValidator validator = new UrlValidator(origin);

        assertThatThrownBy(() -> validator.validate("http://shortener.example/another/path?x=1"))
                .isInstanceOf(InvalidUrlException.class)
                .hasMessageContaining("must not point to this shortener");
    }

    @Test
    void treatsDefaultHttpsPortAsEquivalentAndAllowsDifferentOrigin() {
        PublicOriginConfiguration origin = new PublicOriginConfiguration(
                "https://shortener.example", 8080, false);
        UrlValidator validator = new UrlValidator(origin);

        assertThatThrownBy(() -> validator.validate("https://shortener.example:443/abc"))
                .isInstanceOf(InvalidUrlException.class);
        assertThatCode(() -> validator.validate("https://other.example/abc")).doesNotThrowAnyException();
        assertThatCode(() -> validator.validate("http://shortener.example/abc")).doesNotThrowAnyException();
    }

    @Test
    void rejectsMalformedConfiguredOrigin() {
        org.assertj.core.api.Assertions.assertThatThrownBy(() ->
                new PublicOriginConfiguration("not-an-origin", 8080, false))
                .isInstanceOf(IllegalStateException.class);
    }
}
"},{"path":"src/test/java/com/example/shortener/LinkServiceTest.java","content":"package com.example.shortener;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import java.util.Optional;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.ArgumentCaptor;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

@ExtendWith(MockitoExtension.class)
class LinkServiceTest {

    @Mock
    private LinkRepository linkRepository;

    @Mock
    private ShortCodeGenerator codeGenerator;

    @Mock
    private RedirectEventRepository eventRepository;

    @Test
    void followRecordsTimestampAndRawReferrerAndReturnsDestination() {
        Instant instant = Instant.parse("2026-09-29T10:15:30.123456Z");
        Link link = new Link("https://example.com/target", "abc1234");
        when(linkRepository.findByCode("abc1234")).thenReturn(Optional.of(link));
        when(linkRepository.incrementClickCount("abc1234")).thenReturn(1);

        LinkService service = new LinkService(linkRepository, codeGenerator, eventRepository,
                Clock.fixed(instant, ZoneOffset.UTC));

        assertThat(service.follow("abc1234", "https://referrer.example/article"))
                .isEqualTo("https://example.com/target");

        ArgumentCaptor<RedirectEvent> captor = ArgumentCaptor.forClass(RedirectEvent.class);
        verify(eventRepository).save(captor.capture());
        assertThat(captor.getValue().getOccurredAt()).isEqualTo(instant);
        assertThat(captor.getValue().getReferrer()).isEqualTo("https://referrer.example/article");
        verify(linkRepository).incrementClickCount("abc1234");
    }

    @Test
    void followConvertsMissingAndEmptyReferrersToNull() {
        Link link = new Link("https://example.com/target", "abc1234");
        when(linkRepository.findByCode("abc1234")).thenReturn(Optional.of(link));
        when(linkRepository.incrementClickCount("abc1234")).thenReturn(1);
        LinkService service = new LinkService(linkRepository, codeGenerator, eventRepository,
                Clock.systemUTC());

        service.follow("abc1234", null);
        service.follow("abc1234", "");

        ArgumentCaptor<RedirectEvent> captor = ArgumentCaptor.forClass(RedirectEvent.class);
        verify(eventRepository, org.mockito.Mockito.times(2)).save(captor.capture());
        assertThat(captor.getAllValues()).extracting(RedirectEvent::getReferrer)
                .containsExactly(null, null);
    }

    @Test
    void followDoesNotWriteAnalyticsForUnknownCode() {
        when(linkRepository.findByCode("missing")).thenReturn(Optional.empty());
        LinkService service = new LinkService(linkRepository, codeGenerator, eventRepository,
                Clock.systemUTC());

        org.assertj.core.api.Assertions.assertThatThrownBy(() -> service.follow("missing", "https://ref.example"))
                .isInstanceOf(LinkNotFoundException.class);

        org.mockito.Mockito.verifyNoInteractions(eventRepository);
    }
}
"},{"path":"src/test/java/com/example/shortener/AnalyticsServiceTest.java","content":"package com.example.shortener;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.time.Clock;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneOffset;
import java.util.List;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

@ExtendWith(MockitoExtension.class)
class AnalyticsServiceTest {

    private static final Instant NOW = Instant.parse("2026-09-29T12:00:00Z");

    @Mock
    private LinkService linkService;

    @Mock
    private RedirectEventRepository eventRepository;

    private AnalyticsService analyticsService;

    @BeforeEach
    void setUp() {
        analyticsService = new AnalyticsService(
                linkService,
                eventRepository,
                Clock.fixed(NOW, ZoneOffset.UTC));
    }

    @Test
    void returnsThirtyZeroDaysAndNoReferrersForLinkWithoutEvents() {
        when(eventRepository.countByLink_Code("empty")).thenReturn(0L);
        when(eventRepository.findByLink_CodeAndOccurredAtGreaterThanEqualAndOccurredAtLessThan(
                "empty", Instant.parse("2026-08-31T00:00:00Z"), Instant.parse("2026-09-30T00:00:00Z")))
                .thenReturn(List.of());
        when(eventRepository.findByLink_Code("empty")).thenReturn(List.of());

        LinkAnalyticsResponse response = analyticsService.analytics("empty");

        assertThat(response.totalClicks()).isZero();
        assertThat(response.clicksPerDay()).hasSize(30);
        assertThat(response.clicksPerDay().get(0).date()).isEqualTo(LocalDate.of(2026, 8, 31));
        assertThat(response.clicksPerDay().get(29).date()).isEqualTo(LocalDate.of(2026, 9, 29));
        assertThat(response.clicksPerDay()).allSatisfy(day -> assertThat(day.clicks()).isZero());
        assertThat(response.topReferrers()).isEmpty();
        verify(linkService).getByCode("empty");
    }

    @Test
    void countsUtcDaysIncludesAllTimeTotalAndOrdersAndLimitsReferrers() {
        Link link = new Link("https://destination.example/item", "analytics");
        RedirectEvent old = new RedirectEvent(link, Instant.parse("2020-01-01T00:00:00Z"), "old");
        RedirectEvent todayA = new RedirectEvent(link, Instant.parse("2026-09-29T01:00:00Z"), "beta");
        RedirectEvent todayB = new RedirectEvent(link, Instant.parse("2026-09-29T02:00:00Z"), "alpha");
        RedirectEvent yesterday = new RedirectEvent(link, Instant.parse("2026-09-28T23:30:00Z"), "alpha");
        RedirectEvent empty = new RedirectEvent(link, Instant.parse("2026-09-28T12:00:00Z"), "");
        RedirectEvent nullReferrer = new RedirectEvent(link, Instant.parse("2026-09-27T12:00:00Z"), null);

        List<RedirectEvent> all = List.of(old, todayA, todayB, yesterday, empty, nullReferrer,
                new RedirectEvent(link, NOW, "charlie"),
                new RedirectEvent(link, NOW, "delta"),
                new RedirectEvent(link, NOW, "echo"),
                new RedirectEvent(link, NOW, "foxtrot"),
                new RedirectEvent(link, NOW, "golf"));
        when(eventRepository.countByLink_Code("analytics")).thenReturn((long) all.size());
        when(eventRepository.findByLink_CodeAndOccurredAtGreaterThanEqualAndOccurredAtLessThan(
                "analytics", Instant.parse("2026-08-31T00:00:00Z"), Instant.parse("2026-09-30T00:00:00Z")))
                .thenReturn(all.subList(1, all.size()));
        when(eventRepository.findByLink_Code("analytics")).thenReturn(all);

        LinkAnalyticsResponse response = analyticsService.analytics("analytics");

        assertThat(response.totalClicks()).isEqualTo(11);
        assertThat(response.clicksPerDay()).filteredOn(day -> day.clicks() > 0)
                .extracting(ClickCount::date, ClickCount::clicks)
                .containsExactlyInAnyOrder(
                        org.assertj.core.api.Assertions.tuple(LocalDate.of(2026, 9, 27), 1L),
                        org.assertj.core.api.Assertions.tuple(LocalDate.of(2026, 9, 28), 2L),
                        org.assertj.core.api.Assertions.tuple(LocalDate.of(2026, 9, 29), 7L));
        assertThat(response.topReferrers())
                .extracting(ReferrerCount::referrer, ReferrerCount::clicks)
                .containsExactly(
                        org.assertj.core.api.Assertions.tuple("alpha", 2L),
                        org.assertj.core.api.Assertions.tuple("beta", 1L),
                        org.assertj.core.api.Assertions.tuple("charlie", 1L),
                        org.assertj.core.api.Assertions.tuple("delta", 1L),
                        org.assertj.core.api.Assertions.tuple("echo", 1L));
    }
}
