import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Index;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.ManyToOne;
import jakarta.persistence.Table;
import java.time.Instant;

@Entity
@Table(name = "redirect_events", indexes = {
        @Index(name = "idx_redirect_events_link_time", columnList = "link_id,occurred_at"),
        @Index(name = "idx_redirect_events_link_referrer", columnList = "link_id,referrer")
})
public class RedirectEvent {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY, optional = false)
    @JoinColumn(name = "link_id", nullable = false)
    private Link link;

    @Column(name = "occurred_at", nullable = false)
    private Instant occurredAt;

    @Column(length = 2048)
    private String referrer;

    protected RedirectEvent() {
    }

    public RedirectEvent(Link link, Instant occurredAt, String referrer) {
        this.link = link;
        this.occurredAt = occurredAt;
        this.referrer = referrer;
    }

    public Instant getOccurredAt() {
        return occurredAt;
    }

    public String getReferrer() {
        return referrer;
    }
}
"},{"path":"src/main/java/com/example/shortener/RedirectEventRepository.java","content":"package com.example.shortener;

import java.time.Instant;
import java.time.LocalDate;
import java.util.List;
import org.springframework.data.domain.Pageable;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

public interface RedirectEventRepository extends JpaRepository<RedirectEvent, Long> {
    long countByLink_Code(String code);

    @Query(value = "select cast(e.occurred_at as date) as eventDate, count(*) as clicks "
            + "from redirect_events e join links l on l.id = e.link_id "
            + "where l.code = :code and e.occurred_at >= :fromTime and e.occurred_at < :toTime "
            + "group by cast(e.occurred_at as date)", nativeQuery = true)
    List<DailyCountProjection> countByDay(@Param("code") String code,
                                          @Param("fromTime") Instant fromTime,
                                          @Param("toTime") Instant toTime);

    @Query("select e.referrer as referrer, count(e) as clicks from RedirectEvent e "
            + "where e.link.code = :code and e.referrer is not null and e.referrer <> '' "
            + "group by e.referrer order by count(e) desc, e.referrer asc")
    List<ReferrerCountProjection> topReferrers(@Param("code") String code, Pageable pageable);

    interface DailyCountProjection {
        LocalDate getEventDate();
        long getClicks();
    }

    interface ReferrerCountProjection {
        String getReferrer();
        long getClicks();
    }
}
