"},{"path":"src/main/java/com/example/shortener/PublicOriginConfiguration.java","content":"package com.example.shortener;

import java.net.URI;
import java.util.Locale;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

@Configuration
public class PublicOriginConfiguration {
    @Bean
    public URI publicOrigin(@Value("${app.public-origin:}") String configured,
                            @Value("${server.ssl.enabled:false}") boolean ssl,
                            @Value("${server.port:8080}") int port) {
        String value = configured == null ? "" : configured.trim();
        if (value.isEmpty()) {
            value = (ssl ? "https" : "http") + "://localhost:" + port;
        }
        URI uri;
        try {
            uri = URI.create(value);
        } catch (IllegalArgumentException ex) {
            throw new IllegalStateException("Invalid app.public-origin configuration", ex);
        }
        if (uri.getScheme() == null || uri.getHost() == null || uri.getUserInfo() != null
                || uri.getQuery() != null || uri.getFragment() != null
                || (!uri.getScheme().equalsIgnoreCase("http") && !uri.getScheme().equalsIgnoreCase("https"))) {
            throw new IllegalStateException("app.public-origin must be an HTTP or HTTPS origin");
        }
        return uri;
    }

    public static int effectivePort(URI uri) {
        if (uri.getPort() != -1) return uri.getPort();
        return "https".equalsIgnoreCase(uri.getScheme()) ? 443 : 80;
    }

    public static boolean sameOrigin(URI left, URI right) {
        return left.getScheme().toLowerCase(Locale.ROOT).equals(right.getScheme().toLowerCase(Locale.ROOT))
                && left.getHost().toLowerCase(Locale.ROOT).equals(right.getHost().toLowerCase(Locale.ROOT))
                && effectivePort(left) == effectivePort(right);
    }
}
