"},{"path":"src/main/java/com/example/shortener/UrlValidator.java","content":"package com.example.shortener;

import java.net.URI;
import java.net.URISyntaxException;
import java.util.Locale;
import org.springframework.stereotype.Component;

@Component
public class UrlValidator {
    private static final int MAX_URL_LENGTH = 2048;
    private final URI publicOrigin;

    public UrlValidator(URI publicOrigin) {
        this.publicOrigin = publicOrigin;
    }

    public void validate(String value) {
        if (value == null || value.length() > MAX_URL_LENGTH) throw new InvalidUrlException();
        URI uri;
        try {
            uri = new URI(value);
        } catch (URISyntaxException ex) {
            throw new InvalidUrlException();
        }
        if (uri.getHost() == null || uri.getUserInfo() != null
                || (!"http".equalsIgnoreCase(uri.getScheme()) && !"https".equalsIgnoreCase(uri.getScheme()))) {
            throw new InvalidUrlException();
        }
        if (PublicOriginConfiguration.sameOrigin(uri, publicOrigin)) throw new InvalidUrlException();
    }
}
