"},{"path":"src/main/java/com/example/shortener/LinkService.java","content":"package com.example.shortener;

import java.security.SecureRandom;
import java.time.Clock;
import java.time.Instant;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class LinkService {
    private static final String ALPHABET = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    private final LinkRepository links;
    private final RedirectEventRepository events;
    private final UrlValidator validator;
    private final Clock clock;
    private final SecureRandom random = new SecureRandom();

    public LinkService(LinkRepository links, RedirectEventRepository events, UrlValidator validator) {
        this(links, events, validator, Clock.systemUTC());
    }

    public LinkService(LinkRepository links, RedirectEventRepository events, UrlValidator validator, Clock clock) {
        this.links = links;
        this.events = events;
        this.validator = validator;
        this.clock = clock;
    }

    @Transactional
    public LinkResponse create(String url) {
        validator.validate(url);
        for (int attempt = 0; attempt < 10; attempt++) {
            String code = randomCode();
            if (links.existsByCode(code)) continue;
            try {
                Link link = links.saveAndFlush(new Link(code, url));
                return response(link);
            } catch (DataIntegrityViolationException ignored) {
                // A concurrent creator won this code; try another one.
            }
        }
        throw new IllegalStateException("Unable to generate a short code.");
    }

    @Transactional(readOnly = true)
    public Link getByCode(String code) {
        return links.findByCode(code).orElseThrow(() -> new LinkNotFoundException(code));
    }

    @Transactional(readOnly = true)
    public LinkResponse details(String code) {
        return response(getByCode(code));
    }

    @Transactional
    public String follow(String code, String referrer) {
        Link link = getByCode(code);
        if (links.incrementClickCount(code) != 1) throw new LinkNotFoundException(code);
        String storedReferrer = referrer == null || referrer.isEmpty() ? null
                : referrer.substring(0, Math.min(referrer.length(), 2048));
        events.save(new RedirectEvent(link, Instant.now(clock), storedReferrer));
        return link.getUrl();
    }

    private LinkResponse response(Link link) {
        return new LinkResponse(link.getUrl(), link.getCode(), "/" + link.getCode(), link.getClickCount());
    }

    private String randomCode() {
        StringBuilder result = new StringBuilder(7);
        for (int i = 0; i < 7; i++) result.append(ALPHABET.charAt(random.nextInt(ALPHABET.length())));
        return result.toString();
    }
}
"},{"path":"src/main/java/com/example/shortener/AnalyticsService.java","content":"package com.example.shortener;

import java.time.Clock;
import java.time.LocalDate;
import java.time.ZoneOffset;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.springframework.data.domain.PageRequest;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class AnalyticsService {
    private final LinkService linkService;
    private final RedirectEventRepository events;
    private final Clock clock;

    public AnalyticsService(LinkService linkService, RedirectEventRepository events) {
        this(linkService, events, Clock.systemUTC());
    }

    public AnalyticsService(LinkService linkService, RedirectEventRepository events, Clock clock) {
        this.linkService = linkService;
        this.events = events;
        this.clock = clock;
    }

    @Transactional(readOnly = true)
    public LinkAnalyticsResponse analytics(String code) {
        linkService.getByCode(code);
        LocalDate today = clock.instant().atZone(ZoneOffset.UTC).toLocalDate();
        LocalDate first = today.minusDays(29);
        Map<LocalDate, Long> daily = new HashMap<>();
        events.countByDay(code, first.atStartOfDay(ZoneOffset.UTC).toInstant(),
                today.plusDays(1).atStartOfDay(ZoneOffset.UTC).toInstant())
                .forEach(row -> daily.put(row.getEventDate(), row.getClicks()));
        List<ClickCount> days = new ArrayList<>(30);
        for (LocalDate date = first; !date.isAfter(today); date = date.plusDays(1)) {
            days.add(new ClickCount(date, daily.getOrDefault(date, 0L)));
        }
        List<ReferrerCount> referrers = events.topReferrers(code, PageRequest.of(0, 5)).stream()
                .map(row -> new ReferrerCount(row.getReferrer(), row.getClicks())).toList();
        return new LinkAnalyticsResponse(events.countByLink_Code(code), days, referrers);
    }
}
"},{"path":"src/main/java/com/example/shortener/LinkController.java","content":"package com.example.shortener;

import jakarta.validation.Valid;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/links")
public class LinkController {
    private final LinkService links;
    private final AnalyticsService analytics;

    public LinkController(LinkService links, AnalyticsService analytics) {
        this.links = links;
        this.analytics = analytics;
    }

    @PostMapping
    public ResponseEntity<LinkResponse> create(@Valid @RequestBody CreateLinkRequest request) {
        return ResponseEntity.status(201).body(links.create(request.url()));
    }

    @GetMapping("/{code}/analytics")
    public LinkAnalyticsResponse analytics(@PathVariable String code) {
        return analytics.analytics(code);
    }

    @GetMapping("/{code}")
    public LinkResponse details(@PathVariable String code) {
        return links.details(code);
    }
}
"},{"path":"src/main/java/com/example/shortener/RedirectController.java","content":"package com.example.shortener;

import jakarta.servlet.http.HttpServletRequest;
import org.springframework.http.HttpHeaders;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RestController;

@RestController
public class RedirectController {
    private final LinkService links;

    public RedirectController(LinkService links) {
        this.links = links;
    }

    @GetMapping("/{code}")
    public ResponseEntity<Void> redirect(@PathVariable String code, HttpServletRequest request) {
        String destination = links.follow(code, request.getHeader("Referer"));
        return ResponseEntity.status(302).header(HttpHeaders.LOCATION, destination).build();
    }
}
"},{"path":"src/main/java/com/example/shortener/GlobalExceptionHandler.java","content":"package com.example.shortener;

import jakarta.validation.ConstraintViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

@RestControllerAdvice
public class GlobalExceptionHandler {
    @ExceptionHandler(InvalidUrlException.class)
    public ProblemDetail invalidUrl(InvalidUrlException ex) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST, ex.getMessage());
    }

    @ExceptionHandler({MethodArgumentNotValidException.class, ConstraintViolationException.class})
    public ProblemDetail invalidRequest(Exception ex) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST, "The request is invalid.");
    }

    @ExceptionHandler(LinkNotFoundException.class)
    public ProblemDetail notFound(LinkNotFoundException ex) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, ex.getMessage());
    }

    @ExceptionHandler(IllegalStateException.class)
    public ProblemDetail unavailable(IllegalStateException ex) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.SERVICE_UNAVAILABLE, ex.getMessage());
    }
}
